class Solution {
    public:long long maxCoins(vector<int>& a,vector<int>& b) {
        const long long NEG=LLONG_MIN/4;
        long long dp[3][2];
        for(auto &r:dp)for(long long &x:r)x=NEG;
        long long ans=NEG;
        for(int i=0; i<(int)a.size(); i++) {
            long long nd[3][2];
            for(auto &r:nd)for(long long &x:r)x=NEG;
            nd[0][0]=max(nd[0][0],(long long)a[i]);
            nd[1][1]=max(nd[1][1],(long long)b[i]);
            for(int t=0; t<=2; t++)for(int lane=0; lane<2; lane++) {
                long long v=(lane==0?a[i]:b[i]);
                if(dp[t][lane]!=NEG)nd[t][lane]=max(nd[t][lane],dp[t][lane]+v);
                if(t>0&&dp[t-1][1-lane]!=NEG)nd[t][lane]=max(nd[t][lane],dp[t-1][1-lane]+v);
            }
            for(int t=0; t<=2; t++)for(int lane=0; lane<2; lane++) {
                dp[t][lane]=nd[t][lane];
                ans=max(ans,dp[t][lane]);
            }
        }
        return ans;
    }
}
